mapper.select:
SELECT t.*, (SELECT pk.name FROM sys_tenant_package pk WHERE pk.id = t.package_id AND pk.is_deleted = 0) AS package_name FROM sys_tenant t WHERE t.is_deleted = 0
AND (t.name LIKE CONCAT('%', #{req.keyword}, '%') OR t.code LIKE CONCAT('%', #{req.keyword}, '%'))
AND t.status = #{req.status}
AND t.package_id = #{req.packageId}
ORDER BY t.${req.safeSortField()} ${req.safeSortOrder()}
ORDER BY t.create_time DESC
